import { selectHandoffImageResources, useAssetUrls } from "./stubs.ts";
type AttachmentPreviewHandoffInput = { environmentId: string; threadId: string; serverVisibleTurnItems: {item: any}[]; handoff: Record<string, readonly string[]>; blobPreviews: any; setOptimisticUserMessages: any };
export function useAttachmentPreviewHandoff(input: AttachmentPreviewHandoffInput): infer _ {
  const {
    environmentId,
    threadId,
    serverVisibleTurnItems,
    blobPreviews,
    setOptimisticUserMessages,
  } = input
  const handoffByMessageId = input.handoff
  const serverAttachmentResources = selectHandoffImageResources(
    Object.keys(handoffByMessageId).length === 0
      ? undefined
      : serverVisibleTurnItems.flatMap(({ item }) =>
        item.type === "user_message"
          ? [{ id: item.messageId, role: "user" as const, attachments: item.attachments }]
          : []
      ),
    handoffByMessageId,
  )
  const serverAttachmentUrls = useAssetUrls(environmentId, serverAttachmentResources)
  const serverAttachmentUrlById = new Map(
    serverAttachmentResources.flatMap((resource, index) => {
      const url = serverAttachmentUrls[index]
      return url ? [[resource.attachmentId, url] as const] : []
    }),
  )
  const timelineAttachmentUrlById = ((): infer _ => {
    const urls = new Map(serverAttachmentUrlById)
    for (const row of serverVisibleTurnItems) {
      if (row.item.type !== "user_message") continue
      const handoffUrls = handoffByMessageId[row.item.messageId]
      if (handoffUrls === undefined) continue
      let imageIndex = 0
      for (const attachment of row.item.attachments) {
        if (attachment.type !== "image") continue
        const handoffUrl = handoffUrls[imageIndex]
        imageIndex += 1
        if (handoffUrl !== undefined) urls.set(attachment.id, handoffUrl)
      }
    }
    return urls
  })()
}

